recipes.description:
A list of procmail recipes. Each item must have 'conditions' (list of strings) and 'action' (string). For an item in this list, see 'recipe_item'.
items: {
  conditions: {
    type: list,
    default: [],
    description: "List of regex conditions to match.",
    items: { type: string }
  },
  action: {
    type: string,
    default: "",
    description: "The folder or command to deliver to."
  }
}
